export const clamp=(n,min=0,max=1)=>Math.max(min,Math.min(max,n));
export const ease=n=>{n=clamp(n);return n*n*(3-2*n)};
export function roundedRoute(points,radius=36){if(!points.length)return '';let d=`M${points[0].x},${points[0].y}`;for(let i=1;i<points.length-1;i++){const a=points[i-1],b=points[i],c=points[i+1];const ab=Math.hypot(b.x-a.x,b.y-a.y),bc=Math.hypot(c.x-b.x,c.y-b.y);if(!ab||!bc)continue;const r=Math.min(radius,ab/2,bc/2);if((b.x-a.x)*(c.y-b.y)===(b.y-a.y)*(c.x-b.x)){d+=`L${b.x},${b.y}`;continue}const p={x:b.x+(a.x-b.x)*r/ab,y:b.y+(a.y-b.y)*r/ab},q={x:b.x+(c.x-b.x)*r/bc,y:b.y+(c.y-b.y)*r/bc};d+=`L${p.x},${p.y}Q${b.x},${b.y} ${q.x},${q.y}`}const end=points.at(-1);return d+`L${end.x},${end.y}`}
export function desktopLayout(count){const nodes=Array.from({length:count},(_,i)=>({x:i%2?2920:180,y:500+i*600,sceneX:i%2?1740:260,sceneY:300+i*600,branchX:i%2?2840:260}));const points=[{x:80,y:100},{x:180,y:100}];nodes.forEach((p,i)=>{if(i)points.push({x:nodes[i-1].x,y:p.y-300},{x:p.x,y:p.y-300});points.push({x:p.x,y:p.y})});const last=nodes.at(-1);if(last)points.push({x:last.x,y:last.y+350},{x:1580,y:last.y+350},{x:1580,y:last.y+480});return {nodes,points,width:3100,height:(last?.y||500)+600}}
export function mobileLayout(width,measurements){const margin=40;const nodes=measurements.map((p,i)=>({x:i%2?(p.right??width)-margin:(p.left??0)+margin,y:p.y+52,branchX:i%2?width-margin-38:margin+38}));const points=[{x:width*.64,y:24},{x:nodes[0]?.x||margin,y:24}];nodes.forEach((p,i)=>{if(i){const mid=measurements[i].y-40;points.push({x:nodes[i-1].x,y:mid},{x:p.x,y:mid})}points.push({x:p.x,y:p.y})});const last=nodes.at(-1);if(last)points.push({x:last.x,y:measurements.at(-1).bottom+32},{x:width*.55,y:measurements.at(-1).bottom+32});return {nodes,points}}
export function cameraAt(progress,nodes){if(!nodes.length)return {x:0,y:0,moving:0,nearest:0,local:0};const n=clamp(progress)*Math.max(0,nodes.length-1);const i=Math.min(nodes.length-1,Math.floor(n)),j=Math.min(nodes.length-1,i+1),fraction=n-i,t=ease((fraction-.24)/.56);const center=p=>({x:p.sceneX+(p.x<p.sceneX?500:590),y:p.sceneY+235});const a=center(nodes[i]),b=center(nodes[j]);return {x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t,moving:Math.sin(Math.PI*t),nearest:Math.min(nodes.length-1,Math.round(n)),local:n}}
